        p6: { a: 'βοράν', m: 'η βορά', w: '⭐ «βορά» = η σάρκα ως τροφή σαρκοφάγου, από το «βιβρώσκω» (τρώω). Λέξη σκληρή και επίτηδες: εδώ ο μύθος παραδέχεται ότι η ισορροπία περιλαμβάνει θάνατο.' },

        q1: { a: 'τοῖς μὲν', m: 'σ’ αυτά … τα ζώα', w: '⭐ ΔΕΙΧΝΕΙ ΣΤΑ ΣΑΡΚΟΦΑΓΑ της προηγούμενης πρότασης. Ο Τατάκης προσθέτει το «όμως» για να φανεί η αντίθεση που στα αρχαία την κουβαλάει μόνο το «μὲν … δὲ».' },
        q2: { a: 'ὀλιγογονίαν', m: 'την ιδιότητα να γεννούν λίγους απογόνους', w: '⭐⭐ ΣΥΝΘΕΤΗ: ὀλίγος + γόνος. Μία λέξη στα αρχαία, επτά στα νέα — η σύνθεση είναι το μεγάλο πλεονέκτημα της αρχαίας γλώσσας και φαίνεται εδώ γυμνό.' },
        q3: { a: 'προσῆψε', m: 'ταίριασε', w: '⚠️ ΕΝΑ ΡΗΜΑ ΣΤΑ ΑΡΧΑΙΑ, ΔΥΟ ΦΟΡΕΣ ΣΤΑ ΝΕΑ. Το «προσῆψε» δεν επαναλαμβάνεται στο δεύτερο σκέλος (εννοείται), αλλά ο Τατάκης το ξαναλέει — πάτα το και δες δύο «ταίριασε» να ανάβουν. Ο ίδιος αόριστος με το «προσῆπτεν» της αρχής, σε στιγμιαίο χρόνο.' },
        q4: { a: 'τοῖς δ’', m: 'ενώ σε κείνα', w: 'Το τελευταίο «μὲν … δὲ» της ενότητας, και το πιο σημαντικό: εδώ κλείνει ο κύκλος της ισορροπίας.' },
        q5: { a: 'ἀναλισκομένοις', m: 'που τρώγονταν', w: '⭐ ΜΕΤΟΧΗ ΕΝΕΣΤΩΤΑ ΠΑΘΗΤΙΚΗΣ, από το «ἀναλίσκω» = καταναλώνω, ξοδεύω. Επιθετική, γι’ αυτό γίνεται αναφορική στα νέα. ⚠️ Η ΠΑΘΗΤΙΚΗ ΦΩΝΗ ΕΙΝΑΙ ΤΟ ΝΟΗΜΑ: αυτά δεν κάνουν κάτι, τους γίνεται.' },
        q6: { a: 'ὑπὸ τούτων', m: 'απ’ αυτά', w: '⭐ ΠΟΙΗΤΙΚΟ ΑΙΤΙΟ: «ὑπό» + γενική με παθητική φωνή. Ο κανόνας είναι απόλυτος και εδώ φαίνεται καθαρά.' },
        q7: { a: 'πολυγονίαν', m: 'την πολυγονία', w: '⭐⭐ ΑΚΡΙΒΩΣ ΑΝΤΙΘΕΤΗ ΤΗΣ «ὀλιγογονίας», φτιαγμένη με το ΙΔΙΟ δεύτερο συνθετικό. ⚠️ Εδώ ο Τατάκης ΔΕΝ την αναλύει — την κρατάει αυτούσια, γιατί η λέξη έχει περάσει στα νέα. Δύο σύνθετα δίπλα δίπλα, το ένα μεταφράζεται και το άλλο όχι.' },
        q8: { a: 'σωτηρίαν', m: 'σωτηρία', w: '⭐⭐ Η ΛΕΞΗ ΠΟΥ ΚΛΕΙΝΕΙ ΤΟΝ ΚΥΚΛΟ: «ἄλλην τιν’ … δύναμιν εἰς σωτηρίαν» στην αρχή, «σωτηρίαν τῷ γένει» στο τέλος. Ό,τι άρχισε ως λύση για το ένα ζώο τελειώνει ως ισορροπία για ΟΛΟ το σύστημα.' },
        q9: { a: 'τῷ γένει', m: 'για το γένος τους', w: '⚠️ ΔΟΤΙΚΗ ΧΑΡΙΣΤΙΚΗ: για χάρη του γένους. ⭐ ΤΟ ΕΙΔΟΣ ΞΑΝΑ, ΟΧΙ ΤΟ ΑΤΟΜΟ — το άτομο που τρώγεται χάνεται, το γένος σώζεται επειδή γεννάει πολλά.' },
        q10: { a: 'πορίζων', m: 'βρίσκοντας', w: '⭐ ΤΕΛΙΚΗ ΜΕΤΟΧΗ ΕΝΕΣΤΩΤΑ, ομόρριζη με το «ἐξεπόριζεν». Η τελευταία λέξη της ενότητας είναι ΜΕΤΟΧΗ και όχι ρήμα: η ισορροπία δεν είναι πράξη που τελείωσε, είναι κατάσταση που συνεχίζεται.' }
